-- Bancada descartável. Nenhuma mensagem, nenhuma chamada de rede; rollback integral.
begin;
create temporary table d4 as select gen_random_uuid() shop,gen_random_uuid() person,gen_random_uuid() a,gen_random_uuid() b,gen_random_uuid() plan,gen_random_uuid() grp,gen_random_uuid() cycle,null::jsonb job,null::jsonb body,null::jsonb step;
create function pg_temp.check_d4(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end $$;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select pg_temp.check_d4((select not enabled from public.whatsapp_care_cycle_policy),'Contrato novo não herda liberação do piloto anterior');
update public.whatsapp_send_controls set paused=false where scope='global';
update d4 set shop=(public.register_my_barbershop(gen_random_uuid(),'Ciclo Fictício','America/Sao_Paulo','single',true,'teste','teste','teste')->>'shop_id')::uuid;
select public.platform_create_whatsapp_channel(a,'Ciclo A') from d4;
select public.platform_create_whatsapp_channel(b,'Ciclo B') from d4;
update public.whatsapp_channels set display_phone=case id when (select a from d4) then '+5511800000111' else '+5511800000222' end,status='open' where id in(select a from d4 union all select b from d4);
select public.platform_confirm_whatsapp_control(id,routing_version,display_phone,instance_name,true) from public.whatsapp_channels where id in(select a from d4 union all select b from d4);
select public.platform_plan_whatsapp_distribution(plan,array[shop],false) from d4;
select public.platform_apply_whatsapp_distribution(plan) from d4;
select pg_temp.check_d4((select jsonb_array_length(public.care_cycle_composition(shop))=2 from d4),'Composição da loja usa dois telefones físicos com controle confirmado');
insert into auth.users(id,email,raw_user_meta_data) select person,person||'@example.invalid','{}' from d4;
insert into public.memberships(user_id,barbershop_id,role) select person,shop,'customer' from d4;
insert into public.whatsapp_care_groups(id,barbershop_id,customer_id,customer_phone) select grp,shop,person,'+5511998888666' from d4;
insert into public.whatsapp_group_enrollments(group_id,profile_phone,profile_verified_at) select grp,null,null from d4;
insert into public.whatsapp_care_cycles(id,group_id,customer_phone,consented_numbers,creator_channel_id,creator_instance)
 select cycle,grp,'+5511998888666',public.care_cycle_composition(shop),(public.care_cycle_composition(shop)->0->>'id')::uuid,public.care_cycle_composition(shop)->0->>'instance' from d4;
update public.whatsapp_care_groups set current_cycle_id=(select cycle from d4) where id=(select grp from d4);
select pg_temp.check_d4((select not public.care_cycle_available(cycle) from d4),'Ter números e consentimento não ignora política desligada');
update public.whatsapp_care_cycle_policy set enabled=true;
select pg_temp.check_d4((select public.care_cycle_available(cycle) from d4),'Composição e adesão autenticada elegíveis para preparar, sem confirmar telefone');

create function pg_temp.denied(query text,expected text,label text) returns void language plpgsql as $$begin
 begin execute query;raise exception 'FAIL: %',label;exception when others then
 if sqlerrm like 'FAIL:%' or sqlerrm<>expected then raise;end if;raise notice 'PASS: %',label;end;
end $$;
create temporary table revision_test(id uuid,job jsonb,proof jsonb,ack jsonb);
insert into revision_test default values;
update public.whatsapp_care_cycle_policy set assisted_access_enabled=true where singleton;
update public.whatsapp_care_cycles set created_at=date_trunc('second',clock_timestamp())-interval '5 minutes',expires_at=(date_trunc('second',clock_timestamp())-interval '5 minutes') at time zone 'UTC'+interval '1 year',group_jid='98765-43210@g.us' where id=(select cycle from d4);
update public.whatsapp_care_groups set group_jid='98765-43210@g.us',state='waiting_customer',reason='customer_absent' where id=(select grp from d4);
select set_config('request.jwt.claim.sub',(select person::text from d4),true);
update revision_test set id=(select public.care_phone_revision_start(d.shop,d.grp,g.version,'+5511998888777',array[d.a,d.b],true) from d4 d join public.whatsapp_care_groups g on g.id=d.grp);
select pg_temp.check_d4((select count(*)=1 from public.whatsapp_phone_revisions where customer_id=(select person from d4)),'Uma intenção delimitada para o titular');
select pg_temp.check_d4((select customer_phone='+5511998888666' from public.whatsapp_care_groups where id=(select grp from d4)),'Pedido não troca telefone do grupo antes da prova');
select pg_temp.check_d4((select whatsapp_e164 is null and whatsapp_verified_at is null from public.profiles where id=(select person from d4)),'Pedido não troca nem verifica o perfil');
select pg_temp.check_d4((select not public.care_cycle_available(cycle) from d4),'Motor normal congela durante a revisão');
select pg_temp.check_d4((select public.care_verified_physical(person,'+5511998888777')='+5511998888777' from d4),'Sem prova não adiciona/remove nono dígito');
update revision_test set job=(select public.claim_care_phone_revision(person,shop) from d4);
select pg_temp.check_d4((select job->>'commit_token' is null and job->'payload'->>'commitHash' ~ '^[a-f0-9]{64}$' from revision_test),'Segredo de conclusão não é liberado antes do vínculo no banco');
select pg_temp.check_d4((select public.claim_care_phone_revision(person,shop)->>'waiting'='true' from d4),'Outra aba respeita a posse');
select pg_temp.check_d4((select public.claim_care_phone_revision(gen_random_uuid(),shop) is null from d4),'Outro titular não obtém a intenção');
update revision_test t set proof=(select ((t.job->'payload')-'action')||jsonb_build_object('id',t.id,'groupJid',c.group_jid,'resolvedJid','5511998888777@s.whatsapp.net','phase','pending','createdAt',c.created_at,'expiresAt',c.expires_at,'lookupAt',clock_timestamp(),'requestHash',repeat('a',64)) from public.whatsapp_care_cycles c,d4 where c.id=d4.cycle);
-- payload usa revisionId; a prova usa id. O fornecedor não recebe dados de outra loja.
update revision_test set proof=proof-'revisionId';
select public.record_care_phone_revision(t.id,d.person,(t.job->>'token')::uuid,t.proof,'https://chat.whatsapp.com/FICTICIO123456789') from revision_test t,d4 d;
select pg_temp.check_d4((select public.care_phone_revision_invite(d.shop,t.id)='https://chat.whatsapp.com/FICTICIO123456789' from d4 d,revision_test t),'Convite privado recente só é lido pelo titular');
select pg_temp.denied(format('select public.record_care_phone_revision(%L,%L,%L,%L::jsonb)',t.id,d.person,t.job->>'token',t.proof||'{"phase":"committed"}'),'GROUP_PHONE_PROOF_INVALID','Não pula a confirmação coordenada das duas camadas') from revision_test t,d4 d;
select public.authorize_care_phone_binding(t.id,d.person,(t.job->>'token')::uuid) from revision_test t,d4 d;
select pg_temp.check_d4((select phase='binding' from public.whatsapp_phone_revisions,revision_test t where whatsapp_phone_revisions.id=t.id),'Intenção de bind é durável antes do efeito remoto');
select public.record_care_phone_revision(t.id,d.person,(t.job->>'token')::uuid,t.proof||'{"phase":"bound"}') from revision_test t,d4 d;
select pg_temp.check_d4((select customer_phone='+5511998888777' from public.whatsapp_care_groups where id=(select grp from d4)),'Vínculo comprovado atualiza o telefone físico do mesmo grupo');
select pg_temp.check_d4((select c.group_jid='98765-43210@g.us' and c.admission_id<>r.old_admission_id and c.admission_welcome_id is null from public.whatsapp_care_cycles c join public.whatsapp_phone_revisions r on r.cycle_id=c.id where c.id=(select cycle from d4)),'JID e ciclo preservados, nova admissão exige novo acolhimento');
select pg_temp.check_d4((select not public.care_cycle_available(cycle) from d4),'Mesmo após bind não libera envio antes da conclusão remota');
select pg_temp.check_d4((select verified_at is null from public.whatsapp_phone_aliases where customer_id=(select person from d4)),'Prova do pedido ainda não verifica telefone do perfil');
select public.record_care_phone_revision(t.id,d.person,(t.job->>'token')::uuid,t.proof||'{"phase":"committed"}') from revision_test t,d4 d;
select pg_temp.check_d4((select public.care_cycle_available(cycle) from d4),'Duas camadas conciliadas retomam motor com gates originais');
select pg_temp.check_d4((select not public.care_cycle_send_ready(grp) from d4),'Sem entrada/acolhimento/recibo não libera código');
select pg_temp.check_d4((select public.care_group_physical(person,'+5511998888777',grp,true)='+5511998888777' from d4),'Candidato concluído é resolvido somente no grupo conciliado');
select pg_temp.check_d4((select (public.care_group_read(shop)->>'phone')='+5511998888777' and not (public.care_group_read(shop)->>'phone_confirmed')::boolean from d4),'Interface exibe candidato sem alegar telefone confirmado');
select public.continue_care_phone_revision(d.shop,t.id) from d4 d,revision_test t;
select pg_temp.check_d4((select a.expires_at<=r.deadline from public.whatsapp_care_access a join public.whatsapp_phone_revisions r on r.customer_id=a.customer_id and r.barbershop_id=a.barbershop_id where a.customer_id=(select person from d4)),'Continuação automática não estende o prazo original de consentimento');
select pg_temp.check_d4(not has_table_privilege('authenticated','public.whatsapp_phone_revisions','select'),'Cliente não lê diário privado');
select pg_temp.check_d4(not has_table_privilege('service_role','public.whatsapp_phone_aliases','select'),'Serviço usa contratos em vez de acesso direto a alias');
select pg_temp.check_d4(not has_function_privilege('authenticated','public.record_care_phone_revision(uuid,uuid,uuid,jsonb,text)','execute'),'Cliente não fabrica prova física ou confirma vínculo');
select pg_temp.check_d4(not has_function_privilege('authenticated','public.care_verified_physical(uuid,text)','execute'),'Alias não vira diretório público de telefones');
-- Somente fixture SQL: marca a prova do alias para ensaiar retenção, sem representar OTP real.
update public.whatsapp_phone_aliases set verified_at=clock_timestamp() where customer_id=(select person from d4);
update public.whatsapp_care_cycles set state='closed',closed_at=now()-interval '91 days',cleanup_pending=true where id=(select cycle from d4);
select public.purge_care_group_audit();
select pg_temp.check_d4((select count(*)=1 from public.whatsapp_phone_revisions where id=(select id from revision_test)),'Retenção preserva prova enquanto limpeza não foi comprovada');
update public.whatsapp_care_cycles set cleanup_pending=false where id=(select cycle from d4);
select public.purge_care_group_audit();
select pg_temp.check_d4((select count(*)=0 from public.whatsapp_phone_revisions where id=(select id from revision_test)),'Limpeza comprovada permite minimizar revisão encerrada após 90 dias');
select pg_temp.check_d4((select count(*)=1 from public.whatsapp_phone_aliases where customer_id=(select person from d4) and revision_id is null and verified_at is not null),'Alias verificado da conta sobrevive ao descarte do grupo');
delete from auth.users where id=(select person from d4);
select pg_temp.check_d4((select count(*)=0 from public.whatsapp_phone_aliases where customer_id=(select person from d4)),'Excluir conta elimina também o alias verificado');
rollback;
